fn assert_exact_rename_edits(
    edit: &Value,
    path: &Path,
    source: &str,
    needle: &str,
    occurrences: usize,
    new_name: &str,
) {
    let changes = edit["documentChanges"]
        .as_array()
        .expect("document changes");
    let mut actual = changes
        .iter()
        .flat_map(|change| {
            let uri = change["textDocument"]["uri"]
                .as_str()
                .expect("changed document URI")
                .to_owned();
            change["edits"]
                .as_array()
                .expect("document edits")
                .iter()
                .map(move |edit| {
                    let start = &edit["range"]["start"];
                    let end = &edit["range"]["end"];
                    (
                        uri.clone(),
                        Position::new(
                            start["line"].as_u64().expect("start line") as u32,
                            start["character"].as_u64().expect("start character") as u32,
                        ),
                        Position::new(
                            end["line"].as_u64().expect("end line") as u32,
                            end["character"].as_u64().expect("end character") as u32,
                        ),
                        edit["newText"].as_str().expect("replacement").to_owned(),
                    )
                })
        })
        .collect::<Vec<_>>();
    let mut expected = (0..occurrences)
        .map(|occurrence| {
            let start = position_of(source, needle, occurrence);
            let end = Position::new(
                start.line,
                start.character + needle.encode_utf16().count() as u32,
            );
            (uri(path).to_string(), start, end, new_name.to_owned())
        })
        .collect::<Vec<_>>();
    let sort_edits = |edits: &mut Vec<(String, Position, Position, String)>| {
        edits.sort_by(|left, right| {
            (
                &left.0,
                left.1.line,
                left.1.character,
                left.2.line,
                left.2.character,
                &left.3,
            )
                .cmp(&(
                    &right.0,
                    right.1.line,
                    right.1.character,
                    right.2.line,
                    right.2.character,
                    &right.3,
                ))
        });
    };
    sort_edits(&mut actual);
    sort_edits(&mut expected);
    assert_eq!(actual, expected);
}

fn assert_exact_workspace_edit(
    edit: &Value,
    mut expected: Vec<(String, Position, Position, String)>,
) {
    let changes = edit["documentChanges"]
        .as_array()
        .expect("document changes");
    let mut actual = changes
        .iter()
        .flat_map(|change| {
            let uri = change["textDocument"]["uri"]
                .as_str()
                .expect("changed document URI")
                .to_owned();
            change["edits"]
                .as_array()
                .expect("document edits")
                .iter()
                .map(move |edit| {
                    let start = &edit["range"]["start"];
                    let end = &edit["range"]["end"];
                    (
                        uri.clone(),
                        Position::new(
                            start["line"].as_u64().expect("start line") as u32,
                            start["character"].as_u64().expect("start character") as u32,
                        ),
                        Position::new(
                            end["line"].as_u64().expect("end line") as u32,
                            end["character"].as_u64().expect("end character") as u32,
                        ),
                        edit["newText"].as_str().expect("replacement").to_owned(),
                    )
                })
        })
        .collect::<Vec<_>>();
    actual.sort();
    expected.sort();
    assert_eq!(actual, expected);
}

fn standard_workspace() -> (TempDir, PathBuf, PathBuf, String, String) {
    let temp = tempfile::tempdir().expect("temporary workspace");
    let root = temp.path().join("workspace with spaces");
    let provider = root.join("Provider.pas");
    let main = root.join("Main.pas");
    let provider_source = "unit Provider;\ninterface\nprocedure PublicRoutine;\nimplementation\nprocedure PublicRoutine;\nbegin\nend;\nend.\n".to_string();
    let main_source = "unit Main;\ninterface\nuses Provider;\nimplementation\nprocedure Run;\nbegin\n  PublicRoutine;\nend;\nend.\n".to_string();
    write_file(&provider, &provider_source);
    write_file(&main, &main_source);
    (temp, main, provider, main_source, provider_source)
}

#[test]
fn diagnostics_suppress_unqualified_global_absence_without_a_system_catalogue() {
    let root = tempfile::tempdir().expect("workspace");
    let source_path = root.path().join("Main.pas");
    let source = concat!(
        "unit Main;\n",
        "interface\n",
        "var Known: Integer;\n",
        "implementation\n",
        "procedure Run;\n",
        "begin\n",
        "  Kno := 1;\n",
        "end;\n",
        "end.\n",
    );
    write_file(&source_path, source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&source_path),
                "languageId": "pascal",
                "version": 1,
                "text": source,
            }
        }),
    );

    let diagnostics = diagnostics_for_uri(&mut server, &uri(&source_path));
    let diagnostics = diagnostics["diagnostics"]
        .as_array()
        .expect("diagnostics array");
    assert!(
        diagnostics.is_empty(),
        "an unavailable implicit System namespace cannot prove Kno absent: {diagnostics:?}"
    );
    server.shutdown();
}

#[test]
fn diagnostics_report_a_missing_member_with_utf16_and_crlf_coordinates() {
    let root = tempfile::tempdir().expect("workspace");
    let source_path = root.path().join("Main.pas");
    let source = concat!(
        "unit Main;\r\n",
        "interface\r\n",
        "type\r\n",
        "  TBox = class\r\n",
        "    Value: Integer;\r\n",
        "  end;\r\n",
        "implementation\r\n",
        "procedure Run;\r\n",
        "var Box: TBox;\r\n",
        "begin\r\n",
        "  Writeln('😀'); Box.Missing := 1;\r\n",
        "end;\r\n",
        "end.\r\n",
    );
    write_file(&source_path, source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&source_path),
                "languageId": "pascal",
                "version": 1,
                "text": source,
            }
        }),
    );

    let diagnostics = diagnostics_for_uri(&mut server, &uri(&source_path));
    let diagnostics = diagnostics["diagnostics"]
        .as_array()
        .expect("diagnostics array");
    let diagnostic = diagnostics
        .iter()
        .find(|diagnostic| diagnostic["code"] == "pascal-missing-member")
        .expect("missing member diagnostic");
    assert_eq!(diagnostic["message"], "missing member 'Missing'");
    assert_eq!(
        diagnostic["range"],
        json!({
            "start": {"line": 10, "character": 21},
            "end": {"line": 10, "character": 28},
        })
    );
    server.shutdown();
}

#[test]
fn diagnostics_report_type_and_argument_mismatches_with_utf16_ranges() {
    let root = tempfile::tempdir().expect("workspace");
    let source_path = root.path().join("Main.pas");
    let source = concat!(
        "unit Main;\r\n",
        "interface\r\n",
        "procedure Take(Value: Boolean);\r\n",
        "implementation\r\n",
        "procedure Take(Value: Boolean);\r\n",
        "begin\r\n",
        "end;\r\n",
        "procedure Run;\r\n",
        "var I: Integer; B: Boolean;\r\n",
        "begin\r\n",
        "  Writeln('😀'); B := I; Take(I);\r\n",
        "end;\r\n",
        "end.\r\n",
    );
    write_file(&source_path, source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&source_path),
                "languageId": "pascal",
                "version": 1,
                "text": source,
            }
        }),
    );

    let publication = diagnostics_for_uri(&mut server, &uri(&source_path));
    let diagnostics = publication["diagnostics"]
        .as_array()
        .expect("diagnostics array");
    let assignment_start = position_of(source, "I;", 0);
    let assignment_end = Position::new(assignment_start.line, assignment_start.character + 1);
    let argument_start = position_of(source, "I);", 0);
    let argument_end = Position::new(argument_start.line, argument_start.character + 1);
    let assignment = diagnostics
        .iter()
        .find(|diagnostic| diagnostic["code"] == "pascal-type-mismatch")
        .expect("type mismatch diagnostic");
    assert_eq!(
        assignment["message"],
        "type mismatch: cannot assign 'Integer' to 'Boolean'"
    );
    assert_eq!(
        assignment["range"],
        json!({
            "start": assignment_start,
            "end": assignment_end,
        })
    );

    let argument = diagnostics
        .iter()
        .find(|diagnostic| diagnostic["code"] == "pascal-incompatible-argument")
        .expect("incompatible argument diagnostic");
    assert_eq!(
        argument["message"],
        "incompatible argument: expected 'Boolean', found 'Integer'"
    );
    assert_eq!(
        argument["range"],
        json!({
            "start": argument_start,
            "end": argument_end,
        })
    );
    assert_eq!(
        diagnostics
            .iter()
            .filter(|diagnostic| {
                diagnostic["code"] == "pascal-type-mismatch"
                    || diagnostic["code"] == "pascal-incompatible-argument"
            })
            .count(),
        2
    );
    server.shutdown();
}

#[test]
fn diagnostics_report_override_and_interface_contracts_with_protocol_codes() {
    let root = tempfile::tempdir().expect("workspace");
    let source_path = root.path().join("Main.pas");
    let source = concat!(
        "unit Main;\r\n",
        "interface\r\n",
        "type\r\n",
        "  TObject = class\r\n",
        "  end;\r\n",
        "  TBase = class\r\n",
        "    procedure Run(Value: Integer); virtual;\r\n",
        "  end;\r\n",
        "  IRequired = interface\r\n",
        "    procedure Required;\r\n",
        "  end;\r\n",
        "  TChild = class(TBase)\r\n",
        "    procedure Run(Value: string); override;\r\n",
        "  end;\r\n",
        "  TImplementation = class(TObject, IRequired)\r\n",
        "  end;\r\n",
        "implementation\r\n",
        "procedure TBase.Run(Value: Integer); begin end;\r\n",
        "procedure TChild.Run(Value: string); begin end;\r\n",
        "end.\r\n",
    );
    write_file(&source_path, source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&source_path),
                "languageId": "pascal",
                "version": 1,
                "text": source,
            }
        }),
    );

    let publication = diagnostics_for_uri(&mut server, &uri(&source_path));
    let diagnostics = publication["diagnostics"]
        .as_array()
        .expect("diagnostics array");
    let invalid_override = diagnostics
        .iter()
        .find(|diagnostic| diagnostic["code"] == "pascal-invalid-override")
        .expect("invalid override diagnostic");
    assert_eq!(
        invalid_override["message"],
        "invalid override 'Run': no inherited virtual or dynamic method matches"
    );
    let override_start = position_of(source, "Run(Value: string)", 0);
    assert_eq!(
        invalid_override["range"],
        json!({
            "start": override_start,
            "end": Position::new(override_start.line, override_start.character + 3),
        })
    );

    let missing_interface = diagnostics
        .iter()
        .find(|diagnostic| diagnostic["code"] == "pascal-missing-interface-implementation")
        .expect("missing interface implementation diagnostic");
    assert_eq!(
        missing_interface["message"],
        "class 'TImplementation' does not implement interface method 'Required'"
    );
    let required_start = position_of(source, "TImplementation = class", 0);
    assert_eq!(
        missing_interface["range"],
        json!({
            "start": required_start,
            "end": Position::new(
                required_start.line,
                required_start.character + "TImplementation".encode_utf16().count() as u32,
            ),
        })
    );
    assert_eq!(
        diagnostics
            .iter()
            .filter(|diagnostic| {
                diagnostic["code"] == "pascal-invalid-override"
                    || diagnostic["code"] == "pascal-missing-interface-implementation"
            })
            .count(),
        2
    );
    server.shutdown();
}

#[test]
fn diagnostics_anchor_an_imported_interface_contract_to_the_consumer_physical_uri() {
    let root = tempfile::tempdir().expect("workspace");
    let provider = root.path().join("Provider.pas");
    let main = root.path().join("Main.pas");
    let mut provider_source = String::from(
        "unit Provider;\ninterface\ntype\n  IRequired = interface\n    procedure Required;\n  end;\nimplementation\n",
    );
    provider_source.push_str("end.\n");
    let main_source = concat!(
        "unit Main;\n",
        "interface\n",
        "uses Provider;\n",
        "type\n",
        "  TObject = class\n",
        "  end;\n",
        "  TChild = class(TObject, IRequired)\n",
        "  end;\n",
        "implementation\n",
        "end.\n",
    );
    write_file(&provider, &provider_source);
    write_file(&main, main_source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&main),
                "languageId": "pascal",
                "version": 1,
                "text": main_source,
            }
        }),
    );

    let publication = diagnostics_for_uri(&mut server, &uri(&main));
    let diagnostics = publication["diagnostics"]
        .as_array()
        .expect("consumer diagnostics array");
    let diagnostic = diagnostics
        .iter()
        .find(|diagnostic| diagnostic["code"] == "pascal-missing-interface-implementation")
        .expect("consumer interface diagnostic");
    let class_start = position_of(main_source, "TChild = class", 0);
    assert_eq!(
        diagnostic["range"],
        json!({
            "start": class_start,
            "end": Position::new(
                class_start.line,
                class_start.character + "TChild".encode_utf16().count() as u32,
            ),
        })
    );
    assert_eq!(
        diagnostics
            .iter()
            .filter(|diagnostic| diagnostic["code"] == "pascal-missing-interface-implementation")
            .count(),
        1
    );
    server.shutdown();
}

#[test]
fn diagnostics_refresh_an_imported_interface_contract_after_a_provider_overlay_edit() {
    let root = tempfile::tempdir().expect("workspace");
    let provider = root.path().join("Provider.pas");
    let main = root.path().join("Main.pas");
    let provider_disk = concat!(
        "unit Provider;\n",
        "interface\n",
        "const\n",
        "  DefaultValue = 1;\n",
        "type\n",
        "  IRequired = interface\n",
        "    procedure Required;\n",
        "  end;\n",
        "implementation\n",
        "end.\n",
    );
    let provider_overlay = concat!(
        "unit Provider;\n",
        "interface\n",
        "type\n",
        "  IRequired = interface\n",
        "  end;\n",
        "implementation\n",
        "end.\n",
    );
    let main_source = concat!(
        "unit Main;\n",
        "interface\n",
        "uses Provider;\n",
        "type\n",
        "  TObject = class\n",
        "  end;\n",
        "  TChild = class(TObject, IRequired)\n",
        "  end;\n",
        "implementation\n",
        "end.\n",
    );
    write_file(&provider, provider_disk);
    write_file(&main, main_source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&main),
                "languageId": "pascal",
                "version": 1,
                "text": main_source,
            }
        }),
    );
    let initial = diagnostics_for_uri(&mut server, &uri(&main));
    assert!(
        initial["diagnostics"]
            .as_array()
            .expect("initial diagnostics")
            .iter()
            .any(|diagnostic| diagnostic["code"] == "pascal-missing-interface-implementation")
    );

    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&provider),
                "languageId": "pascal",
                "version": 2,
                "text": provider_overlay,
            }
        }),
    );
    let refreshed = diagnostics_for_uri(&mut server, &uri(&main));
    assert!(
        refreshed["diagnostics"]
            .as_array()
            .expect("refreshed diagnostics")
            .iter()
            .all(|diagnostic| diagnostic["code"] != "pascal-missing-interface-implementation"),
        "provider overlay should remove the stale interface obligation: {refreshed}"
    );
    server.shutdown();
}

