#[test]
fn diagnostics_suppress_shared_include_claims_for_both_root_open_orders() {
    for open_order in [["A.pas", "B.pas"], ["B.pas", "A.pas"]] {
        let root = tempfile::tempdir().expect("workspace");
        let a = root.path().join("A.pas");
        let b = root.path().join("B.pas");
        let shared = root.path().join("Shared.inc");
        let a_source = concat!(
            "unit A;\n",
            "interface\n",
            "type TShared = record Value: Integer; end;\n",
            "var SharedBox: TShared;\n",
            "implementation\n",
            "{$I Shared.inc}\n",
            "end.\n",
        );
        let b_source = concat!(
            "unit B;\n",
            "interface\n",
            "type TShared = record Other: Integer; end;\n",
            "var SharedBox: TShared;\n",
            "implementation\n",
            "{$I Shared.inc}\n",
            "end.\n",
        );
        let shared_source = "procedure Run; begin SharedBox.Value := 1; end;\n";
        write_file(&a, a_source);
        write_file(&b, b_source);
        write_file(&shared, shared_source);

        let mut server = TestServer::launch();
        server.initialize(root.path(), Value::Null);
        for (index, file_name) in open_order.into_iter().enumerate() {
            let path = root.path().join(file_name);
            let source = if file_name == "A.pas" {
                a_source
            } else {
                b_source
            };
            server.send_notification(
                "textDocument/didOpen",
                json!({
                    "textDocument": {
                        "uri": uri(&path),
                        "languageId": "pascal",
                        "version": 1,
                        "text": source,
                    }
                }),
            );
            let root_diagnostics = diagnostics_for_uri(&mut server, &uri(&path));
            assert!(
                root_diagnostics["diagnostics"].as_array().is_some(),
                "root diagnostics publication must be retained: {root_diagnostics}"
            );
            if index == 0 {
                // The first root may be the only known context.  The second
                // root must force a fresh ownership decision below.
                let _ = server.diagnostic_with_timeout(&uri(&shared), Duration::from_secs(1));
                continue;
            }

            let include_diagnostics =
                server.diagnostic_with_timeout(&uri(&shared), Duration::from_secs(1));
            if open_order[0] == "B.pas" {
                let diagnostics = include_diagnostics
                    .as_ref()
                    .expect("opening the second root must retract the first root claim");
                assert!(
                    diagnostics["diagnostics"]
                        .as_array()
                        .expect("include diagnostics")
                        .iter()
                        .all(|diagnostic| {
                            !(diagnostic["code"] == "pascal-missing-member"
                                && diagnostic["message"] == "missing member 'Value'")
                        }),
                    "shared include claim must be retracted for open order {open_order:?}: {diagnostics}"
                );
            } else if let Some(diagnostics) = include_diagnostics {
                assert!(
                    diagnostics["diagnostics"]
                        .as_array()
                        .expect("include diagnostics")
                        .iter()
                        .all(|diagnostic| {
                            !(diagnostic["code"] == "pascal-missing-member"
                                && diagnostic["message"] == "missing member 'Value'")
                        }),
                    "shared include claim must be suppressed for open order {open_order:?}: {diagnostics}"
                );
            }
        }
        server.shutdown();
    }
}

#[test]
fn diagnostics_suppress_shared_include_claims_for_incomplete_competing_roots_and_overlays() {
    let shared_source = "procedure Run; begin SharedBox.SharedName := 1; end;\n";
    let a_empty = concat!(
        "unit A;\n",
        "interface\n",
        "type TShared = record SharedName: Integer; end;\n",
        "var SharedBox: TShared;\n",
        "implementation\n",
        "end.\n",
    );
    let a_complete = concat!(
        "unit A;\n",
        "interface\n",
        "type TShared = record SharedName: Integer; end;\n",
        "var SharedBox: TShared;\n",
        "implementation\n",
        "{$I Shared.inc}\n",
        "end.\n",
    );
    let a_incomplete = concat!(
        "unit A;\n",
        "interface\n",
        "type TShared = record SharedName: Integer; end;\n",
        "var SharedBox: TShared;\n",
        "implementation\n",
        "{$I Shared.inc}\n",
        "{$I Missing.inc}\n",
        "end.\n",
    );
    let b_source = concat!(
        "unit B;\n",
        "interface\n",
        "type TShared = record Other: Integer; end;\n",
        "var SharedBox: TShared;\n",
        "type TOwn = record Value: Integer; end;\n",
        "var OwnBox: TOwn;\n",
        "implementation\n",
        "{$I Shared.inc}\n",
        "procedure Other; begin OwnBox.OwnTypoo := 1; end;\n",
        "end.\n",
    );

    for open_order in [["A.pas", "B.pas"], ["B.pas", "A.pas"]] {
        let root = tempfile::tempdir().expect("workspace");
        let a = root.path().join("A.pas");
        let b = root.path().join("B.pas");
        let shared = root.path().join("Shared.inc");
        write_file(&a, a_empty);
        write_file(&b, b_source);
        write_file(&shared, shared_source);

        let mut server = TestServer::launch();
        server.initialize(root.path(), Value::Null);
        for file_name in open_order {
            let path = root.path().join(file_name);
            let source = if file_name == "A.pas" {
                a_empty
            } else {
                b_source
            };
            server.send_notification(
                "textDocument/didOpen",
                json!({
                    "textDocument": {
                        "uri": uri(&path),
                        "languageId": "pascal",
                        "version": 1,
                        "text": source,
                    }
                }),
            );
            let root_diagnostics = diagnostics_for_uri(&mut server, &uri(&path));
            if file_name == "B.pas" {
                assert!(
                    root_diagnostics["diagnostics"]
                        .as_array()
                        .expect("B diagnostics")
                        .iter()
                        .any(|diagnostic| diagnostic["message"] == "missing member 'OwnTypoo'"),
                    "the competing root's independent local claim must remain visible: {root_diagnostics}"
                );
            }
        }

        let initial = server
            .diagnostic_with_timeout(&uri(&shared), Duration::from_secs(1))
            .expect("the sole include owner must publish the initial claim");
        assert!(
            initial["diagnostics"]
                .as_array()
                .expect("initial shared diagnostics")
                .iter()
                .any(|diagnostic| diagnostic["message"] == "missing member 'SharedName'"),
            "initial claim should be visible before the competing root owns Shared.inc: {initial}"
        );

        server.send_notification(
            "textDocument/didChange",
            json!({
                "textDocument": {"uri": uri(&a), "version": 2},
                "contentChanges": [{"text": a_complete}],
            }),
        );
        let complete = diagnostics_for_uri(&mut server, &uri(&a));
        assert!(
            complete["diagnostics"]
                .as_array()
                .expect("complete A diagnostics")
                .iter()
                .all(|diagnostic| diagnostic["message"]
                    != "include expansion was incomplete; lint diagnostics were withheld")
        );
        let _ = diagnostics_for_uri(&mut server, &uri(&b));
        assert!(
            diagnostics_for_uri_until(
                &mut server,
                &uri(&shared),
                Duration::from_secs(3),
                |publication| {
                    publication["diagnostics"]
                        .as_array()
                        .expect("shared diagnostics")
                        .iter()
                        .all(|diagnostic| diagnostic["message"] != "missing member 'SharedName'")
                }
            )
            .is_some(),
            "adding the competing include must retract the prior claim"
        );

        server.send_notification(
            "textDocument/didChange",
            json!({
                "textDocument": {"uri": uri(&a), "version": 3},
                "contentChanges": [{"text": a_incomplete}],
            }),
        );
        let incomplete = diagnostics_for_uri(&mut server, &uri(&a));
        assert!(
            incomplete["diagnostics"]
                .as_array()
                .expect("incomplete A diagnostics")
                .iter()
                .any(|diagnostic| diagnostic["message"]
                    == "include expansion was incomplete; lint diagnostics were withheld")
        );
        if let Some(publication) =
            diagnostics_for_uri_until(&mut server, &uri(&shared), Duration::from_secs(1), |_| true)
        {
            assert!(
                publication["diagnostics"]
                    .as_array()
                    .expect("shared diagnostics")
                    .iter()
                    .all(|diagnostic| diagnostic["message"] != "missing member 'SharedName'"),
                "incomplete overlay must not restore a physical include claim: {publication}"
            );
        }

        server.send_notification(
            "textDocument/didChange",
            json!({
                "textDocument": {"uri": uri(&a), "version": 4},
                "contentChanges": [{"text": a_complete}],
            }),
        );
        let complete_again = diagnostics_for_uri(&mut server, &uri(&a));
        assert!(
            complete_again["diagnostics"]
                .as_array()
                .expect("complete A diagnostics after removing Missing.inc")
                .iter()
                .all(|diagnostic| diagnostic["message"]
                    != "include expansion was incomplete; lint diagnostics were withheld")
        );
        if let Some(publication) =
            diagnostics_for_uri_until(&mut server, &uri(&shared), Duration::from_secs(1), |_| true)
        {
            assert!(
                publication["diagnostics"]
                    .as_array()
                    .expect("shared diagnostics")
                    .iter()
                    .all(|diagnostic| diagnostic["message"] != "missing member 'SharedName'"),
                "removing the missing include must not restore a claim while both roots remain owners: {publication}"
            );
        }

        server.send_notification(
            "textDocument/didClose",
            json!({"textDocument": {"uri": uri(&a)}}),
        );
        assert!(
            diagnostics_for_uri_until(
                &mut server,
                &uri(&shared),
                Duration::from_secs(3),
                |publication| {
                    publication["diagnostics"]
                        .as_array()
                        .expect("shared diagnostics after close")
                        .iter()
                        .any(|diagnostic| diagnostic["message"] == "missing member 'SharedName'")
                }
            )
            .is_some(),
            "closing the competing root must restore the sole-owner claim"
        );
        server.shutdown();
    }
}

#[test]
fn diagnostics_suppress_shared_claims_for_unknown_suffix_ownership() {
    let shared_source = "procedure Run; begin SharedBox.SharedName := 1; end;\n";
    let a_source = concat!(
        "unit A;\n",
        "interface\n",
        "type TShared = record SharedName: Integer; end;\n",
        "var SharedBox: TShared;\n",
        "implementation\n",
        "{$I Missing.inc}\n",
        "{$IFDEF FEATURE}\n",
        "{$I Shared.inc}\n",
        "{$ENDIF}\n",
        "end.\n",
    );
    let b_source = concat!(
        "unit B;\n",
        "interface\n",
        "type TShared = record Other: Integer; end;\n",
        "var SharedBox: TShared;\n",
        "type TOwn = record Value: Integer; end;\n",
        "var OwnBox: TOwn;\n",
        "implementation\n",
        "{$I Shared.inc}\n",
        "procedure Other; begin OwnBox.OwnTypoo := 1; end;\n",
        "end.\n",
    );

    for open_order in [["A.pas", "B.pas"], ["B.pas", "A.pas"]] {
        let root = tempfile::tempdir().expect("workspace");
        let a = root.path().join("A.pas");
        let b = root.path().join("B.pas");
        let shared = root.path().join("Shared.inc");
        write_file(&a, a_source);
        write_file(&b, b_source);
        write_file(&shared, shared_source);

        let mut server = TestServer::launch();
        server.initialize(root.path(), Value::Null);
        for file_name in open_order {
            let path = root.path().join(file_name);
            let source = if file_name == "A.pas" {
                a_source
            } else {
                b_source
            };
            server.send_notification(
                "textDocument/didOpen",
                json!({
                    "textDocument": {
                        "uri": uri(&path),
                        "languageId": "pascal",
                        "version": 1,
                        "text": source,
                    }
                }),
            );
            let root_diagnostics = diagnostics_for_uri(&mut server, &uri(&path));
            if file_name == "B.pas" {
                assert!(
                    root_diagnostics["diagnostics"]
                        .as_array()
                        .expect("B diagnostics")
                        .iter()
                        .any(|diagnostic| diagnostic["message"] == "missing member 'OwnTypoo'"),
                    "the competing root's independent local claim must remain visible: {root_diagnostics}"
                );
            }
        }

        // Re-run the incomplete root to exercise the publication refresh
        // barrier in both open orders, including the order that first
        // published B's physical include claim.
        server.send_notification(
            "textDocument/didChange",
            json!({
                "textDocument": {"uri": uri(&a), "version": 2},
                "contentChanges": [{"text": a_source}],
            }),
        );
        let _ = diagnostics_for_uri(&mut server, &uri(&a));
        let saw_physical_claim = std::cell::Cell::new(false);
        let saw_retraction = std::cell::Cell::new(false);
        let _ = diagnostics_for_uri_until(
            &mut server,
            &uri(&shared),
            Duration::from_secs(3),
            |publication| {
                let has_claim = publication["diagnostics"]
                    .as_array()
                    .expect("shared diagnostics")
                    .iter()
                    .any(|diagnostic| diagnostic["message"] == "missing member 'SharedName'");
                if has_claim {
                    saw_physical_claim.set(true);
                    false
                } else {
                    saw_retraction.set(true);
                    true
                }
            },
        );
        if open_order[0] == "B.pas" {
            assert!(
                saw_physical_claim.get(),
                "B-first order must exercise retraction of the prior physical claim"
            );
            assert!(
                saw_retraction.get(),
                "B-first order must publish the retracted physical state"
            );
        }
        server.shutdown();
    }
}

#[test]
fn numeric_compiler_version_rename_edits_only_the_active_branch() {
    let root = tempfile::tempdir().expect("workspace");
    let source_path = root.path().join("Probe.pas");
    let source = concat!(
        "unit Probe;\n",
        "interface\n",
        "var Counter: Integer;\n",
        "implementation\n",
        "procedure P;\n",
        "begin\n",
        "{$IF CompilerVersion = 18.50}\n",
        "  Counter := 1;\n",
        "{$ELSE}\n",
        "  Counter := 2;\n",
        "{$ENDIF}\n",
        "end;\n",
        "end.\n",
    );
    write_file(&source_path, source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), json!({"compilerVersion": "18.5"}));
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&source_path),
                "languageId": "pascal",
                "version": 1,
                "text": source
            }
        }),
    );
    let request_id = RequestId::from("numeric-compiler-version-rename".to_string());
    server.send_request(
        request_id.clone(),
        "textDocument/rename",
        json!({
            "textDocument": {"uri": uri(&source_path)},
            "position": {"line": 2, "character": 4},
            "newName": "Updated"
        }),
    );
    let response = server.response(&request_id);
    assert!(response.error.is_none(), "rename failed: {response:?}");
    let edit = response.result.expect("rename edit");
    assert_exact_rename_edits(&edit, &source_path, source, "Counter", 2, "Updated");
    assert!(!edit.to_string().contains("\"line\":9"));
    server.shutdown();
}

#[test]
fn typed_address_alias_rename_edits_only_the_active_branch() {
    let root = tempfile::tempdir().expect("workspace");
    let source_path = root.path().join("Probe.pas");
    let source = concat!(
        "unit Probe;\n",
        "interface\n",
        "var Counter: Integer;\n",
        "implementation\n",
        "procedure P;\n",
        "begin\n",
        "{$TYPEDADDRESS OFF}\n",
        "{$IFOPT T+}\n",
        "  Counter := 1;\n",
        "{$ELSE}\n",
        "  Counter := 2;\n",
        "{$ENDIF}\n",
        "end;\n",
        "end.\n",
    );
    write_file(&source_path, source);

    let mut server = TestServer::launch();
    server.initialize(root.path(), json!({"compilerOptions": {"T": true}}));
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&source_path),
                "languageId": "pascal",
                "version": 1,
                "text": source
            }
        }),
    );
    let request_id = RequestId::from("typed-address-alias-rename".to_string());
    server.send_request(
        request_id.clone(),
        "textDocument/rename",
        json!({
            "textDocument": {"uri": uri(&source_path)},
            "position": {"line": 2, "character": 4},
            "newName": "Updated"
        }),
    );
    let response = server.response(&request_id);
    assert!(response.error.is_none(), "rename failed: {response:?}");
    let edit = response.result.expect("rename edit");
    assert_exact_workspace_edit(
        &edit,
        vec![
            (
                uri(&source_path).to_string(),
                Position::new(2, 4),
                Position::new(2, 11),
                "Updated".to_string(),
            ),
            (
                uri(&source_path).to_string(),
                Position::new(10, 2),
                Position::new(10, 9),
                "Updated".to_string(),
            ),
        ],
    );
    assert!(!edit.to_string().contains("\"line\":8"));
    server.shutdown();
}

#[cfg(unix)]
#[test]
fn delphi_overrides_user_config_navigates_to_native_source() {
    let environment = tempfile::tempdir().unwrap();
    let root = tempfile::tempdir().unwrap();
    let sdk = tempfile::tempdir().unwrap();
    let main = root.path().join("Main.pas");
    let provider = sdk.path().join("source/Provider.pas");
    let source = "unit Main;\ninterface\nuses Provider;\nimplementation\nend.\n";
    write_file(&main, source);
    write_file(&provider, "unit Provider; interface implementation end.");
    write_file(
        &root.path().join("Main.dproj"),
        r#"
<Project><PropertyGroup><MainSource>Main.pas</MainSource>
<DCC_UnitSearchPath>$(BDS)\source</DCC_UnitSearchPath>
</PropertyGroup></Project>
"#,
    );
    write_file(
        &environment.path().join("config/delphi-tools/config.toml"),
        &format!(
            "[properties]\nBDS = 'C:\\SDK'\n[[path_mappings]]\nfrom = 'C:\\SDK'\nto = '{}'\n",
            sdk.path().display()
        ),
    );
    let mut server = TestServer::launch_with_environment(environment);
    server.initialize(root.path(), Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&main),
                "languageId": "pascal",
                "version": 1,
                "text": source
            }
        }),
    );
    let id = RequestId::from("mapped-definition".to_string());
    server.send_request(
        id.clone(),
        "textDocument/definition",
        json!({
            "textDocument": {"uri": uri(&main)},
            "position": {"line": 2, "character": 5}
        }),
    );
    let response = server.response(&id);
    assert!(response.error.is_none(), "{response:?}");
    let value = response.result.unwrap();
    let locations: Vec<lsp_types::Location> = serde_json::from_value(value).unwrap();
    assert_eq!(locations.len(), 1);
    assert_eq!(locations[0].uri, uri(&provider));
    server.shutdown();
    assert_eq!(fs::read_to_string(main).unwrap(), source);
}

