#[test]
fn unit_references_and_highlights_use_bound_alias_identity_and_complete_prefixes() {
    let temp = tempfile::tempdir().unwrap();
    let provider = temp.path().join("Vendor.Core.pas");
    let decoy = temp.path().join("Legacy.pas");
    let consumer = temp.path().join("Consumer.pas");
    let provider_source =
        "unit Vendor.Core;\ninterface\ntype\n  TThing = class\n  end;\nimplementation\nend.\n";
    let decoy_source =
        "unit Legacy;\ninterface\ntype\n  TThing = class\n  end;\nimplementation\nend.\n";
    let consumer_source = "unit Consumer;\ninterface\nuses Legacy;\nimplementation\nprocedure Run;\nbegin\n  Legacy.TThing;\nend;\nend.\n";
    write_file(&provider, provider_source);
    write_file(&decoy, decoy_source);
    write_file(&consumer, consumer_source);
    write_file(
        &temp.path().join("App.dproj"),
        "<Project><PropertyGroup><MainSource>Consumer.pas</MainSource><DCC_Namespace>Vendor</DCC_Namespace><DCC_UnitAlias>Legacy=Vendor.Core</DCC_UnitAlias></PropertyGroup></Project>",
    );

    let mut server = TestServer::launch();
    server.initialize(temp.path(), Value::Null);

    let references_id = RequestId::from("bound-unit-references".to_string());
    server.send_request(
        references_id.clone(),
        "textDocument/references",
        json!({
            "textDocument": {"uri": uri(&provider)},
            "position": position_of(provider_source, "Vendor.Core", 0),
            "context": {"includeDeclaration": true}
        }),
    );
    let references = result_locations(server.response(&references_id));
    assert_eq!(
        references,
        vec![
            json!({
                "uri": uri(&consumer).to_string(),
                "range": {
                    "start": {"line": 2, "character": 5},
                    "end": {"line": 2, "character": 11}
                }
            }),
            json!({
                "uri": uri(&consumer).to_string(),
                "range": {
                    "start": {"line": 6, "character": 2},
                    "end": {"line": 6, "character": 8}
                }
            }),
            json!({
                "uri": uri(&provider).to_string(),
                "range": {
                    "start": {"line": 0, "character": 5},
                    "end": {"line": 0, "character": 16}
                }
            })
        ]
    );

    let highlights_id = RequestId::from("bound-unit-highlights".to_string());
    server.send_request(
        highlights_id.clone(),
        "textDocument/documentHighlight",
        json!({
            "textDocument": {"uri": uri(&consumer)},
            "position": position_of(consumer_source, "Legacy", 0)
        }),
    );
    let highlights = server.response(&highlights_id);
    assert!(highlights.error.is_none(), "{highlights:?}");
    assert_eq!(
        highlights.result.unwrap().as_array().unwrap().clone(),
        vec![
            json!({
                "range": {
                    "start": {"line": 2, "character": 5},
                    "end": {"line": 2, "character": 11}
                },
                "kind": 1
            }),
            json!({
                "range": {
                    "start": {"line": 6, "character": 2},
                    "end": {"line": 6, "character": 8}
                },
                "kind": 1
            })
        ]
    );

    let provider_highlights_id = RequestId::from("bound-provider-unit-highlights".to_string());
    server.send_request(
        provider_highlights_id.clone(),
        "textDocument/documentHighlight",
        json!({
            "textDocument": {"uri": uri(&provider)},
            "position": position_of(provider_source, "Vendor.Core", 0)
        }),
    );
    let provider_highlights = server.response(&provider_highlights_id);
    assert!(
        provider_highlights.error.is_none(),
        "{provider_highlights:?}"
    );
    assert_eq!(
        provider_highlights
            .result
            .unwrap()
            .as_array()
            .unwrap()
            .clone(),
        vec![json!({
            "range": {
                "start": {"line": 0, "character": 5},
                "end": {"line": 0, "character": 16}
            },
            "kind": 1
        })]
    );
    server.shutdown();
}

#[test]
fn namespaced_unit_references_cover_each_declaration_component_and_unopened_consumers() {
    let temp = tempfile::tempdir().unwrap();
    let provider = temp.path().join("Ns.Provider.pas");
    let consumer = temp.path().join("Consumer.pas");
    let shortened = temp.path().join("ShortConsumer.pas");
    let provider_source = "unit Ns.Provider;\ninterface\nconst Value = 1;\nimplementation\nend.\n";
    let consumer_source = "unit Consumer;\ninterface\nuses Ns.Provider;\nimplementation\nprocedure Run;\nbegin\n  Ns.Provider.Value;\nend;\nend.\n";
    let shortened_source = "unit ShortConsumer;\ninterface\nuses Provider;\nimplementation\nprocedure Run;\nbegin\n  Provider.Value;\nend;\nend.\n";
    write_file(&provider, provider_source);
    write_file(&consumer, consumer_source);
    write_file(&shortened, shortened_source);
    write_file(
        &temp.path().join("App.dproj"),
        "<Project><PropertyGroup><MainSource>Consumer.pas</MainSource><DCC_Namespace>Ns</DCC_Namespace></PropertyGroup></Project>",
    );

    let mut server = TestServer::launch();
    server.initialize(temp.path(), Value::Null);

    let mut expected = vec![
        json!({
            "uri": uri(&consumer).to_string(),
            "range": {
                "start": {"line": 2, "character": 5},
                "end": {"line": 2, "character": 16}
            }
        }),
        json!({
            "uri": uri(&consumer).to_string(),
            "range": {
                "start": {"line": 6, "character": 2},
                "end": {"line": 6, "character": 13}
            }
        }),
        json!({
            "uri": uri(&shortened).to_string(),
            "range": {
                "start": {"line": 2, "character": 5},
                "end": {"line": 2, "character": 13}
            }
        }),
        json!({
            "uri": uri(&shortened).to_string(),
            "range": {
                "start": {"line": 6, "character": 2},
                "end": {"line": 6, "character": 10}
            }
        }),
    ];
    expected.sort_by_key(|value| value.to_string());

    for (component, component_position) in [("Ns", 5_u32), ("Provider", 8_u32)] {
        for include_declaration in [false, true] {
            let id = RequestId::from(format!(
                "namespaced-provider-{component}-{include_declaration}"
            ));
            server.send_request(
                id.clone(),
                "textDocument/references",
                json!({
                    "textDocument": {"uri": uri(&provider)},
                    "position": {"line": 0, "character": component_position},
                    "context": {"includeDeclaration": include_declaration}
                }),
            );
            let response = server.response(&id);
            assert!(
                response.error.is_none(),
                "{component} response: {response:?}"
            );
            let mut actual = result_locations(response);
            let mut expected_for_request = expected.clone();
            if include_declaration {
                expected_for_request.push(json!({
                    "uri": uri(&provider).to_string(),
                    "range": {
                        "start": {"line": 0, "character": 5},
                        "end": {"line": 0, "character": 16}
                    }
                }));
            }
            assert_eq!(actual.len(), expected_for_request.len());
            actual.sort_by_key(|value| value.to_string());
            expected_for_request.sort_by_key(|value| value.to_string());
            assert_eq!(actual, expected_for_request, "component {component}");
        }
    }
    server.shutdown();
}

#[test]
fn namespaced_unit_references_follow_project_alias_identity() {
    let temp = tempfile::tempdir().unwrap();
    let provider = temp.path().join("Ns.Provider.pas");
    let consumer = temp.path().join("AliasConsumer.pas");
    let provider_source = "unit Ns.Provider;\ninterface\nconst Value = 1;\nimplementation\nend.\n";
    let consumer_source = "unit AliasConsumer;\ninterface\nuses Legacy;\nimplementation\nprocedure Run;\nbegin\n  Legacy.Value;\nend;\nend.\n";
    write_file(&provider, provider_source);
    write_file(&consumer, consumer_source);
    write_file(
        &temp.path().join("App.dproj"),
        "<Project><PropertyGroup><MainSource>AliasConsumer.pas</MainSource><DCC_Namespace>Ns</DCC_Namespace><DCC_UnitAlias>Legacy=Ns.Provider</DCC_UnitAlias></PropertyGroup></Project>",
    );

    let mut server = TestServer::launch();
    server.initialize(temp.path(), Value::Null);
    for include_declaration in [false, true] {
        let id = RequestId::from(format!("namespaced-provider-alias-{include_declaration}"));
        server.send_request(
            id.clone(),
            "textDocument/references",
            json!({
                "textDocument": {"uri": uri(&provider)},
                "position": {"line": 0, "character": 8},
                "context": {"includeDeclaration": include_declaration}
            }),
        );
        let response = server.response(&id);
        assert!(response.error.is_none(), "alias response: {response:?}");
        let mut actual = result_locations(response);
        let mut expected = vec![
            json!({
                "uri": uri(&consumer).to_string(),
                "range": {
                    "start": {"line": 2, "character": 5},
                    "end": {"line": 2, "character": 11}
                }
            }),
            json!({
                "uri": uri(&consumer).to_string(),
                "range": {
                    "start": {"line": 6, "character": 2},
                    "end": {"line": 6, "character": 8}
                }
            }),
        ];
        if include_declaration {
            expected.push(json!({
                "uri": uri(&provider).to_string(),
                "range": {
                    "start": {"line": 0, "character": 5},
                    "end": {"line": 0, "character": 16}
                }
            }));
        }
        actual.sort_by_key(|value| value.to_string());
        expected.sort_by_key(|value| value.to_string());
        assert_eq!(actual, expected);
    }
    server.shutdown();
}

#[test]
fn document_highlights_ignore_huge_unreadable_unrelated_trees_and_dependency_occurrences() {
    let temp = tempfile::tempdir().unwrap();
    let provider = temp.path().join("Provider.pas");
    let main = temp.path().join("Main.pas");
    let unrelated = temp.path().join("unrelated/Huge.pas");
    let unreadable = temp.path().join("unrelated/Unreadable.pas");
    let mut provider_source = String::from(
        "unit Provider;\ninterface\nconst SharedValue = 1;\nimplementation\nprocedure Noise;\nbegin\n",
    );
    for _ in 0..10_000 {
        provider_source.push_str("  Log(SharedValue);\n");
    }
    provider_source.push_str("end;\nend.\n");
    let main_source = "unit Main;\ninterface\nuses Provider;\nimplementation\nprocedure Run;\nbegin\n  Log(SharedValue);\nend;\nend.\n";
    let huge_unrelated = format!(
        "unit Huge;\ninterface\nconst SharedValue = 1;\nimplementation\n{}\n",
        "x".repeat(2 * 1024 * 1024)
    );
    let unreadable_source =
        "unit Unreadable;\ninterface\nconst SharedValue = 1;\nimplementation\nend.\n";
    write_file(&provider, &provider_source);
    write_file(&main, main_source);
    write_file(&unrelated, &huge_unrelated);
    write_file(&unreadable, unreadable_source);
    #[cfg(unix)]
    {
        let mut permissions = fs::metadata(&unreadable).unwrap().permissions();
        permissions.set_mode(0o000);
        fs::set_permissions(&unreadable, permissions).unwrap();
    }

    let mut server = TestServer::launch();
    server.initialize(temp.path(), Value::Null);
    let id = RequestId::from("isolated-highlight-tree".to_string());
    server.send_request(
        id.clone(),
        "textDocument/documentHighlight",
        json!({
            "textDocument": {"uri": uri(&main)},
            "position": position_of(main_source, "SharedValue", 0)
        }),
    );
    let response = server.response(&id);
    assert!(response.error.is_none(), "{response:?}");
    let highlights = response.result.unwrap().as_array().unwrap().clone();
    assert_eq!(
        highlights.len(),
        1,
        "dependency occurrences and unrelated unreadable/huge files must not affect local highlights"
    );
    assert_eq!(
        highlights[0]["range"],
        json!({
            "start": {"line": 6, "character": 6},
            "end": {"line": 6, "character": 17}
        })
    );
    server.shutdown();
}

#[test]
fn document_highlights_reject_incomplete_import_binding_snapshots() {
    let temp = tempfile::tempdir().unwrap();
    let main = temp.path().join("Main.pas");
    let provider_a = temp.path().join("ProviderA.pas");
    let provider_b = temp.path().join("ProviderB.pas");
    let main_source = "unit Main;\ninterface\nuses ProviderA, ProviderB;\nimplementation\nprocedure Run;\nbegin\n  Log(SharedValue);\nend;\nend.\n";
    let provider_source =
        "unit ProviderA;\ninterface\nconst SharedValue = 1;\nimplementation\nend.\n";
    let provider_b_source = provider_source.replace("ProviderA", "ProviderB");
    write_file(&main, main_source);
    write_file(&provider_a, provider_source);
    write_file(&provider_b, &provider_b_source);

    let request = json!({
        "textDocument": {"uri": uri(&main)},
        "position": position_of(main_source, "SharedValue", 0)
    });
    let mut incomplete_server = TestServer::launch();
    incomplete_server.initialize(temp.path(), json!({"maxFiles": 2}));
    let incomplete_id = RequestId::from("incomplete-import-highlights".to_string());
    incomplete_server.send_request(
        incomplete_id.clone(),
        "textDocument/documentHighlight",
        request.clone(),
    );
    let incomplete = incomplete_server.response(&incomplete_id);
    assert!(
        incomplete.error.is_some(),
        "incomplete import binding must not guess the retained provider: {incomplete:?}"
    );
    assert!(incomplete.result.is_none());
    incomplete_server.shutdown();

    let mut complete_server = TestServer::launch();
    complete_server.initialize(temp.path(), json!({"maxFiles": 3}));
    let complete_id = RequestId::from("complete-import-highlights".to_string());
    complete_server.send_request(
        complete_id.clone(),
        "textDocument/documentHighlight",
        request,
    );
    let complete = complete_server.response(&complete_id);
    assert!(complete.error.is_none(), "{complete:?}");
    assert!(complete.result.unwrap().as_array().unwrap().is_empty());
    complete_server.shutdown();
}

