#[test]
fn code_action_withholds_interface_cycles_but_allows_an_implementation_back_edge() {
    let run_without_action =
        |consumer_source: &str, provider_source: &str, middle_source: Option<&str>, id: &str| {
            let temp = tempfile::tempdir().expect("temporary workspace");
            let root = temp.path().join("fixture");
            let consumer = root.join("Consumer.pas");
            write_file(&consumer, consumer_source);
            write_file(&root.join("Provider.pas"), provider_source);
            if let Some(middle_source) = middle_source {
                write_file(&root.join("Middle.pas"), middle_source);
            }
            let mut server = TestServer::launch();
            server.initialize_without_document_changes(&root, Value::Null);
            server.send_notification(
                "textDocument/didOpen",
                json!({
                    "textDocument": {
                        "uri": uri(&consumer),
                        "languageId": "pascal",
                        "version": 1,
                        "text": consumer_source,
                    }
                }),
            );
            let actions = request_missing_unit_actions(
                &mut server,
                &consumer,
                consumer_source,
                "MissingType",
                id,
            );
            assert!(
                actions.is_empty(),
                "uncertain or illegal interface cycle must be withheld: {actions:?}"
            );
            server.shutdown();
        };

    run_without_action(
        concat!(
            "unit Consumer;\n",
            "interface\n",
            "type TAlias = MissingType;\n",
            "implementation\n",
            "end.\n",
        ),
        concat!(
            "unit Provider;\n",
            "interface\n",
            "uses Consumer;\n",
            "type MissingType = class end;\n",
            "implementation\n",
            "end.\n",
        ),
        None,
        "direct-interface-cycle",
    );
    run_without_action(
        concat!(
            "unit Consumer;\n",
            "interface\n",
            "type TAlias = MissingType;\n",
            "implementation\n",
            "end.\n",
        ),
        concat!(
            "unit Provider;\n",
            "interface\n",
            "uses Middle;\n",
            "type MissingType = class end;\n",
            "implementation\n",
            "end.\n",
        ),
        Some(concat!(
            "unit Middle;\n",
            "interface\n",
            "uses Consumer;\n",
            "implementation\n",
            "end.\n",
        )),
        "transitive-interface-cycle-provider",
    );

    let temp = tempfile::tempdir().expect("temporary workspace");
    let root = temp.path().join("fixture");
    let consumer = root.join("Consumer.pas");
    let provider_source = concat!(
        "unit Provider;\n",
        "interface\n",
        "uses Consumer;\n",
        "type MissingType = class end;\n",
        "implementation\n",
        "end.\n",
    );
    let consumer_source = concat!(
        "unit Consumer;\n",
        "interface\n",
        "implementation\n",
        "procedure Run;\n",
        "var Value: MissingType;\n",
        "begin\n",
        "  Value := 1;\n",
        "end;\n",
        "end.\n",
    );
    write_file(&consumer, consumer_source);
    write_file(&root.join("Provider.pas"), provider_source);
    let mut server = TestServer::launch();
    server.initialize_without_document_changes(&root, Value::Null);
    server.send_notification(
        "textDocument/didOpen",
        json!({
            "textDocument": {
                "uri": uri(&consumer),
                "languageId": "pascal",
                "version": 1,
                "text": consumer_source,
            }
        }),
    );
    let actions = request_missing_unit_actions(
        &mut server,
        &consumer,
        consumer_source,
        "MissingType",
        "implementation-back-edge",
    );
    assert_eq!(actions.len(), 1, "legal implementation import: {actions:?}");
    let updated =
        apply_workspace_edit_to_source(consumer_source, &actions[0]["edit"], &uri(&consumer));
    server.send_notification(
        "textDocument/didChange",
        json!({
            "textDocument": {"uri": uri(&consumer), "version": 2},
            "contentChanges": [{"text": updated}]
        }),
    );
    let definition_id = RequestId::from("implementation-back-edge-definition".to_string());
    server.send_request(
        definition_id.clone(),
        "textDocument/definition",
        navigation_params(&consumer, &updated, "MissingType", 0),
    );
    let locations = result_locations(server.response(&definition_id));
    assert_eq!(locations.len(), 1);
    assert_eq!(
        locations[0]["uri"],
        uri(&root.join("Provider.pas")).to_string()
    );
    server.shutdown();
}

#[test]
fn code_actions_require_a_provider_export_kind_compatible_with_the_use_site() {
    let run_case = |provider_declaration: &str,
                    consumer_source: &str,
                    identifier: &str,
                    expected_action: bool,
                    expected_fragment: Option<&str>,
                    id: &str| {
        let temp = tempfile::tempdir().expect("temporary workspace");
        let root = temp.path().join("fixture");
        let consumer = root.join("Consumer.pas");
        let provider = root.join("Provider.pas");
        write_file(&consumer, consumer_source);
        write_file(
            &provider,
            &format!("unit Provider;\ninterface\n{provider_declaration}\nimplementation\nend.\n"),
        );
        let mut server = TestServer::launch();
        server.initialize_without_document_changes(&root, Value::Null);
        server.send_notification(
            "textDocument/didOpen",
            json!({
                "textDocument": {
                    "uri": uri(&consumer),
                    "languageId": "pascal",
                    "version": 1,
                    "text": consumer_source,
                }
            }),
        );
        let actions =
            request_missing_unit_actions(&mut server, &consumer, consumer_source, identifier, id);
        assert_eq!(
            actions.len() == 1,
            expected_action,
            "kind case actions: {actions:?}"
        );
        if expected_action {
            let updated = apply_workspace_edit_to_source(
                consumer_source,
                &actions[0]["edit"],
                &uri(&consumer),
            );
            server.send_notification(
                "textDocument/didChange",
                json!({
                    "textDocument": {"uri": uri(&consumer), "version": 2},
                    "contentChanges": [{"text": updated}]
                }),
            );
            let definition_id = RequestId::from(format!("{id}-definition"));
            server.send_request(
                definition_id.clone(),
                "textDocument/definition",
                navigation_params(&consumer, &updated, identifier, 0),
            );
            let locations = result_locations(server.response(&definition_id));
            assert_eq!(
                locations.len(),
                1,
                "provider kind definition: {locations:?}"
            );
            assert_eq!(locations[0]["uri"], uri(&provider).to_string());
            let hover_id = RequestId::from(format!("{id}-hover"));
            server.send_request(
                hover_id.clone(),
                "textDocument/hover",
                navigation_params(&consumer, &updated, identifier, 0),
            );
            let hover = server.response(&hover_id);
            assert!(hover.error.is_none(), "provider kind hover: {hover:?}");
            let hover_result = hover.result.expect("provider kind hover result");
            let hover_text = hover_result["contents"]["value"]
                .as_str()
                .expect("provider kind hover text");
            if let Some(expected_fragment) = expected_fragment {
                assert!(
                    hover_text
                        .to_ascii_lowercase()
                        .contains(&expected_fragment.to_ascii_lowercase()),
                    "hover must retain the expected export {expected_fragment:?}: {hover_text:?}"
                );
            }
        }
        server.shutdown();
    };

    let type_use = concat!(
        "unit Consumer;\n",
        "interface\n",
        "type TAlias = MissingType;\n",
        "implementation\n",
        "end.\n",
    );
    run_case(
        "const MissingType = 1;",
        type_use,
        "MissingType",
        false,
        None,
        "type-constant",
    );
    run_case(
        "procedure MissingType;",
        type_use,
        "MissingType",
        false,
        None,
        "type-routine",
    );
    run_case(
        "type MissingType = class end;",
        type_use,
        "MissingType",
        true,
        Some("type"),
        "type-type",
    );
    let value_use = concat!(
        "unit Consumer;\n",
        "interface\n",
        "implementation\n",
        "var Sink: Integer;\n",
        "procedure Run;\n",
        "begin\n",
        "  Sink := MissingValue;\n",
        "end;\n",
        "end.\n",
    );
    run_case(
        "const MissingValue = 1;",
        value_use,
        "MissingValue",
        true,
        Some("= 1"),
        "value-constant",
    );
    run_case(
        "var MissingValue: Integer;",
        value_use,
        "MissingValue",
        true,
        Some(": Integer"),
        "value-variable",
    );
    let call_use = concat!(
        "unit Consumer;\n",
        "interface\n",
        "implementation\n",
        "procedure Run;\n",
        "begin\n",
        "  MissingProc;\n",
        "end;\n",
        "end.\n",
    );
    run_case(
        "var MissingProc: Integer;",
        call_use,
        "MissingProc",
        false,
        None,
        "call-variable",
    );
    run_case(
        "procedure MissingProc;",
        call_use,
        "MissingProc",
        true,
        Some("MissingProc"),
        "call-routine",
    );
}

#[test]
fn code_actions_preserve_argument_value_roles_and_reject_procedural_values() {
    let run_case = |provider_declaration: &str,
                    consumer_source: &str,
                    identifier: &str,
                    expected_action: bool,
                    id: &str| {
        let temp = tempfile::tempdir().expect("temporary workspace");
        let root = temp.path().join("fixture");
        let consumer = root.join("Consumer.pas");
        let provider = root.join("Provider.pas");
        write_file(&consumer, consumer_source);
        write_file(
            &provider,
            &format!("unit Provider;\ninterface\n{provider_declaration}\nimplementation\nend.\n"),
        );
        let mut server = TestServer::launch();
        server.initialize_without_document_changes(&root, Value::Null);
        server.send_notification(
            "textDocument/didOpen",
            json!({
                "textDocument": {
                    "uri": uri(&consumer),
                    "languageId": "pascal",
                    "version": 1,
                    "text": consumer_source,
                }
            }),
        );
        let actions =
            request_missing_unit_actions(&mut server, &consumer, consumer_source, identifier, id);
        assert_eq!(
            actions.len() == 1,
            expected_action,
            "argument-role action result: {actions:?}"
        );
        if expected_action {
            let updated = apply_workspace_edit_to_source(
                consumer_source,
                &actions[0]["edit"],
                &uri(&consumer),
            );
            server.send_notification(
                "textDocument/didChange",
                json!({
                    "textDocument": {"uri": uri(&consumer), "version": 2},
                    "contentChanges": [{"text": updated}]
                }),
            );
            let definition_id = RequestId::from(format!("{id}-definition"));
            server.send_request(
                definition_id.clone(),
                "textDocument/definition",
                navigation_params(&consumer, &updated, identifier, 0),
            );
            let locations = result_locations(server.response(&definition_id));
            assert_eq!(
                locations.len(),
                1,
                "argument-role definition: {locations:?}"
            );
            assert_eq!(locations[0]["uri"], uri(&provider).to_string());
        }
        server.shutdown();
    };

    let argument_use = concat!(
        "unit Consumer;\n",
        "interface\n",
        "implementation\n",
        "procedure Sink(Value: Integer);\n",
        "begin\n",
        "end;\n",
        "procedure Run;\n",
        "begin\n",
        "  Sink(MissingValue);\n",
        "end;\n",
        "end.\n",
    );
    run_case(
        "const MissingValue = 1;",
        argument_use,
        "MissingValue",
        true,
        "argument-constant-value",
    );
    run_case(
        "var MissingValue: Integer;",
        argument_use,
        "MissingValue",
        true,
        "argument-variable-value",
    );
    run_case(
        "procedure MissingValue;",
        argument_use,
        "MissingValue",
        false,
        "argument-procedure-value",
    );
    run_case(
        "function MissingValue: Integer;",
        argument_use,
        "MissingValue",
        false,
        "argument-function-value",
    );
    run_case(
        "{$IF MaybeUndefined}\nconst MissingValue = 1;\n{$ENDIF}",
        argument_use,
        "MissingValue",
        false,
        "argument-unknown-conditional",
    );

    let bare_call = concat!(
        "unit Consumer;\n",
        "interface\n",
        "implementation\n",
        "procedure Run;\n",
        "begin\n",
        "  MissingProc;\n",
        "end;\n",
        "end.\n",
    );
    run_case(
        "procedure MissingProc;",
        bare_call,
        "MissingProc",
        true,
        "bare-procedure-call",
    );
}

